contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address[] memory tos, uint v, uint decimals) public returns (bool) {
        require(tos.length > 0);
        bool reverted;
        bool ok = false;
        try c.transfer(from, address(this), tos, v, decimals) returns (bool r) {
            reverted = false;
            ok = r;
        } catch {
            reverted = true;
        }
        assert(!reverted && ok);
        return true;
    }

    fallback(bytes calldata input) external payable returns (bytes memory) {
        bytes4 sel;
        assembly { sel := calldataload(0) }
        if (sel == bytes4(keccak256("transferFrom(address,address,uint256)"))) {
            return abi.encode(true);
        }
        revert();
    }

    receive() external payable {}
}

